  function rebuildIndexes(){data.plannedEvents=data.plannedEvents||[];{const PV=globalThis.VanorPursuits;if(PV){const m=new Map((data.pursuits||[]).map(p=>[p.id,p]));for(const w of data.work)if(PV.isPursuit(w))m.set(w.id,w);data.pursuits=[...m.values()];data.work=data.work.filter(w=>!PV.isPursuit(w));}else data.pursuits=data.pursuits||[];}{const X=['todo','job','stripstate','candidate','capture'];const m=new Map((data.extra||[]).map(w=>[w.id,w]));for(const w of data.work)if(X.includes(w.kind))m.set(w.id,w);data.extra=[...m.values()];data.work=data.work.filter(w=>!X.includes(w.kind));}recordMap=new Map(data.records.map(r=>[r.id,r]));workMap=new Map(data.work.map(w=>[w.id,w]));workByRecord=new Map();for(const w of data.work){const rows=workByRecord.get(w.recordId)||[];rows.push(w);workByRecord.set(w.recordId,rows);}candidateList=D.candidateRecords(data.records);identityFirst=new Map();for(const r of data.records){const key=identityKey(r);const dd=data.decisions[r.id];if(dd&&(dd.status==='Archive'||dd.mergedInto))continue;if(key!=='|'&&!identityFirst.has(key))identityFirst.set(key,r.id);}statusCache=new Map();}
  const isFirstIdentity=r=>identityFirst.get(identityKey(r))===r.id;
  const queue=()=>candidateList.filter(r=>matchesOwner(actualOwner(r))&&VanorFit.matches(r,app.fit)&&(app.segment==='All segments'||((decision(r.id).segment||r.segment||VanorFit.segment(r)))===app.segment)&&regionOk(r)&&searchRecord(r)&&((app.reviewTab==='Archived'&&statusFor(r)==='Archive')||(app.reviewTab==='All'&&statusFor(r)!=='Archive')||(!['All','Archived'].includes(app.reviewTab)&&statusFor(r)===app.reviewTab))&&(app.reviewTab==='Archived'||isFirstIdentity(r))).sort((a,b)=>VanorFit.score(b)-VanorFit.score(a)||Number(b.classification==='Known contact')-Number(a.classification==='Known contact')||Number(a.kind==='lead')-Number(b.kind==='lead'));
  async function reload(){data=await repo.load();rebuildIndexes();}
  function selectedRecord(){const q=queue();if(!q.some(r=>r.id===app.selected))app.selected=q[app.reviewPage*40]?.id||q[0]?.id||'';return q.find(r=>r.id===app.selected);}
  function toast(message,error=false,undo=null){clearTimeout(toastTimer);toastHtml=`<div class="toast ${error?'error':''}" role="${error?'alert':'status'}">${E(message)}${undo?'<button data-action="undo">Undo</button>':''}<button data-action="dismissToast" aria-label="Dismiss">${icon('close')}</button></div>`;app.undo=undo;renderLayers();toastTimer=setTimeout(()=>{toastHtml='';renderLayers();},error?13000:5500);}
  function showSave(label,failed=false){saveState=label;saveFailed=failed;const e=element.querySelector('[data-save-state]');if(e){e.innerHTML=`<span class="dot ${failed?'warn':''}"></span>${E(label||repo.label)}`;e.classList.toggle('save-error',failed);}}
  function cleanEntity(e){const r={...e};delete r._auditWarning;return r;}
  async function saveDecision(id,patch,event){const old=decision(id);const updated=await repo.saveDecision({...cleanEntity(old),...patch,id},old._rev,event);data.decisions[id]=updated;statusCache.delete(id);if(updated._auditWarning)toast(updated._auditWarning,true);showSave(repo.label);return updated;}
