  async function openRecord(id){if(!await flush())return;app.drawer=null;app.view='record';app.newLeads=false;app.selected=id;app.mobileNav=false;render();window.scrollTo(0,0);}
  function openModal({title,deck='',body,submit='Save',onSubmit=null,wide=false}){lastFocus=document.activeElement;modalTitle=title;modalCallback=onSubmit;modalHtml=`<div class="modal-shade"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><div><h2 id="modal-title">${E(title)}</h2>${deck?`<p>${E(deck)}</p>`:''}</div>${btn('','closeModal','','icon ghost','close')}</header><form data-modal-form><div class="modal-body">${body}<div class="form-error" role="alert"></div></div><footer class="modal-actions">${btn(onSubmit?'Cancel':'Close','closeModal')}${onSubmit?`<button class="btn primary" type="submit">${E(submit)}</button>`:''}</footer></form></section></div>`;renderLayers();setTimeout(()=>{const first=element.querySelector('.modal input:not([type=hidden]),.modal textarea,.modal select,.modal [data-action="closeModal"]');first?.focus();},30);}
  function withExit(sel,fn){const el=element.querySelector(sel);const reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;if(!el||reduce){fn();return;}el.classList.add('closing');setTimeout(fn,170);}
