    if(event.key==='Tab'){const dialog=element.querySelector('.modal')||element.querySelector('.drawer');if(dialog){const els=[...dialog.querySelectorAll('button:not([disabled]),a,input:not([type=hidden]),select,textarea,[tabindex="0"]')].filter(e=>e.offsetParent!==null);if(!els.length)return;const first=els[0],last=els.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}}
